PROGRAM Tank_Cascade
VAR
  tank1_level: REAL;
  tank2_level: REAL;
  tank3_level: REAL;
  pump1_on: BOOL;
  pump2_on: BOOL;
  pump3_on: BOOL;
  flow_rate: REAL;
  total_volume: REAL;
  overflow_alarm: BOOL;
  underflow_alarm: BOOL;
  auto_mode: BOOL;
END_VAR
BEGIN
  IF auto_mode THEN
    IF (tank1_level > 95.0) OR (tank2_level > 95.0) OR (tank3_level > 95.0) THEN
      overflow_alarm := TRUE;
      pump1_on := FALSE;
      pump2_on := FALSE;
      pump3_on := FALSE;
    ELSE
      overflow_alarm := FALSE;
      IF tank1_level < 30.0 THEN
        pump1_on := TRUE;
      ELSIF tank1_level > 80.0 THEN
        pump1_on := FALSE;
      END_IF;
      IF (tank1_level > 70.0) AND (tank2_level < 40.0) THEN
        pump2_on := TRUE;
      ELSIF (tank1_level < 50.0) OR (tank2_level > 85.0) THEN
        pump2_on := FALSE;
      END_IF;
      IF (tank2_level > 70.0) AND (tank3_level < 40.0) THEN
        pump3_on := TRUE;
      ELSIF (tank2_level < 50.0) OR (tank3_level > 85.0) THEN
        pump3_on := FALSE;
      END_IF;
    END_IF;
    IF (tank1_level < 5.0) OR (tank2_level < 5.0) OR (tank3_level < 5.0) THEN
      underflow_alarm := TRUE;
    ELSE
      underflow_alarm := FALSE;
    END_IF;
    flow_rate := 0.0;
    IF pump1_on THEN flow_rate := flow_rate + 10.0; END_IF;
    IF pump2_on THEN flow_rate := flow_rate + 10.0; END_IF;
    IF pump3_on THEN flow_rate := flow_rate + 10.0; END_IF;
    total_volume := total_volume + (flow_rate * 0.1 / 60.0);
  ELSE
    pump1_on := FALSE;
    pump2_on := FALSE;
    pump3_on := FALSE;
    overflow_alarm := FALSE;
    underflow_alarm := FALSE;
  END_IF;
END_PROGRAM
PROGRAM Quality_Control
VAR
  total_count: INT;
  good_count: INT;
  bad_count: INT;
  batch_number: INT;
  quality_percent: REAL;
  running: BOOL;
  batch_complete: BOOL;
  quality_alarm: BOOL;
  state: INT;
END_VAR
BEGIN
  CASE state OF
    0: (* STOPPED *)
      batch_complete := FALSE;
      quality_alarm := FALSE;
      IF running THEN
        state := 1;
        total_count := 0;
      END_IF;
    1: (* RUNNING *)
      total_count := good_count + bad_count;
      IF total_count > 0 THEN
        quality_percent := INT_TO_REAL(good_count * 100) / INT_TO_REAL(total_count);
      ELSE
        quality_percent := 100.0;
      END_IF;
      IF (total_count > 10) AND (quality_percent < 95.0) THEN
        state := 3; (* ALARM *)
        quality_alarm := TRUE;
      END_IF;
      IF total_count >= 100 THEN
        state := 2; (* BATCH_DONE *)
        batch_complete := TRUE;
        batch_number := batch_number + 1;
      END_IF;
      IF NOT running THEN
        state := 0; (* STOPPED *)
      END_IF;
    2: (* BATCH_DONE *)
      (* Wait for reset *)
      IF NOT running THEN
        state := 0;
        total_count := 0;
        batch_complete := FALSE;
      END_IF;
    3: (* ALARM *)
      (* Quality failure - stop production *)
      quality_alarm := TRUE;
      IF NOT running THEN
        state := 0;
        quality_alarm := FALSE;
      END_IF;
  END_CASE;
END_PROGRAM
PROGRAM HVAC_Control
VAR
  zone1_temp: REAL;
  zone2_temp: REAL;
  zone3_temp: REAL;
  zone4_temp: REAL;
  avg_temp: REAL;
  setpoint: REAL;
  heating_on: BOOL;
  cooling_on: BOOL;
  zone1_alarm: BOOL;
  zone2_alarm: BOOL;
  zone3_alarm: BOOL;
  zone4_alarm: BOOL;
  system_enable: BOOL;
  eco_mode: BOOL;
END_VAR
BEGIN
  IF system_enable THEN
    avg_temp := (zone1_temp + zone2_temp + zone3_temp + zone4_temp) / 4.0;
    zone1_alarm := (zone1_temp < 15.0) OR (zone1_temp > 30.0);
    zone2_alarm := (zone2_temp < 15.0) OR (zone2_temp > 30.0);
    zone3_alarm := (zone3_temp < 15.0) OR (zone3_temp > 30.0);
    zone4_alarm := (zone4_temp < 15.0) OR (zone4_temp > 30.0);
    IF eco_mode THEN
      IF avg_temp < (INT_TO_REAL(REAL_TO_INT(setpoint)) - 2.0) THEN
        heating_on := TRUE;
        cooling_on := FALSE;
      ELSIF avg_temp > (INT_TO_REAL(REAL_TO_INT(setpoint)) + 2.0) THEN
        heating_on := FALSE;
        cooling_on := TRUE;
      ELSE
        heating_on := FALSE;
        cooling_on := FALSE;
      END_IF;
    ELSE
      IF avg_temp < (INT_TO_REAL(REAL_TO_INT(setpoint)) - 0.5) THEN
        heating_on := TRUE;
        cooling_on := FALSE;
      ELSIF avg_temp > (INT_TO_REAL(REAL_TO_INT(setpoint)) + 0.5) THEN
        heating_on := FALSE;
        cooling_on := TRUE;
      END_IF;
    END_IF;
  ELSE
    heating_on := FALSE;
    cooling_on := FALSE;
    zone1_alarm := FALSE;
    zone2_alarm := FALSE;
    zone3_alarm := FALSE;
    zone4_alarm := FALSE;
  END_IF;
END_PROGRAM

